-- CPF integration closure lifecycle: field encryption, data quality and webhook
CREATE TABLE CPF_FIELD_ENCRYPTION_LEDGER (
 RECORD_ID VARCHAR(64) NOT NULL, FIELD_NAME VARCHAR(64) NOT NULL, CLASSIFICATION VARCHAR(64) NOT NULL, KEY_VERSION VARCHAR(64) NOT NULL, SEARCH_TOKEN VARCHAR(1000), ENVELOPE_PAYLOAD BYTEA NOT NULL, MASKED_PREVIEW VARCHAR(1000) NOT NULL, ROW_VERSION BIGINT NOT NULL, UPDATED_AT TIMESTAMPTZ NOT NULL, PRIMARY KEY (RECORD_ID, FIELD_NAME)
);
CREATE INDEX IX_CPF_FIELD_ENC_TOKEN ON CPF_FIELD_ENCRYPTION_LEDGER (FIELD_NAME, SEARCH_TOKEN);
CREATE TABLE CPF_DATA_QUALITY_RULE (RULE_ID VARCHAR(64) NOT NULL, RULE_VERSION BIGINT NOT NULL, FIELD_NAME VARCHAR(64) NOT NULL, EXPRESSION VARCHAR(1000) NOT NULL, SEVERITY VARCHAR(64) NOT NULL, RULE_STATE VARCHAR(64) NOT NULL, UPDATED_BY VARCHAR(64) NOT NULL, UPDATED_AT TIMESTAMPTZ NOT NULL, PRIMARY KEY (RULE_ID, RULE_VERSION));
CREATE TABLE CPF_DATA_QUALITY_QUARANTINE (QUARANTINE_ID VARCHAR(64) NOT NULL, RECORD_ID VARCHAR(64) NOT NULL, ORIGINAL_PAYLOAD BYTEA NOT NULL, CORRECTED_PAYLOAD BYTEA, QUARANTINE_STATE VARCHAR(64) NOT NULL, VIOLATION_SUMMARY VARCHAR(1000) NOT NULL, ROW_VERSION BIGINT NOT NULL, UPDATED_BY VARCHAR(64), UPDATE_REASON VARCHAR(1000), UPDATED_AT TIMESTAMPTZ NOT NULL, PRIMARY KEY (QUARANTINE_ID));
CREATE INDEX IX_CPF_DQ_QUARANTINE_STATE ON CPF_DATA_QUALITY_QUARANTINE (QUARANTINE_STATE, UPDATED_AT);
CREATE TABLE CPF_WEBHOOK_ENDPOINT (ENDPOINT_ID VARCHAR(64) NOT NULL, CALLBACK_URI VARCHAR(1000) NOT NULL, SECRET_VERSION VARCHAR(64) NOT NULL, ALLOWED_EVENT_TYPES VARCHAR(1000) NOT NULL, ENABLED BOOLEAN NOT NULL, ROW_VERSION BIGINT NOT NULL, UPDATED_BY VARCHAR(64) NOT NULL, UPDATE_REASON VARCHAR(1000) NOT NULL, UPDATED_AT TIMESTAMPTZ NOT NULL, PRIMARY KEY (ENDPOINT_ID));
CREATE TABLE CPF_WEBHOOK_DELIVERY (DELIVERY_ID VARCHAR(64) NOT NULL, ENDPOINT_ID VARCHAR(64) NOT NULL, EVENT_ID VARCHAR(64) NOT NULL, EVENT_TYPE VARCHAR(64) NOT NULL, IDEMPOTENCY_KEY VARCHAR(64) NOT NULL, DELIVERY_SEQUENCE BIGINT NOT NULL, DELIVERY_STATE VARCHAR(64) NOT NULL, ATTEMPT_COUNT BIGINT NOT NULL, NEXT_ATTEMPT_AT TIMESTAMPTZ NOT NULL, LAST_ERROR VARCHAR(1000), ROW_VERSION BIGINT NOT NULL, UPDATED_AT TIMESTAMPTZ NOT NULL, PRIMARY KEY (DELIVERY_ID), CONSTRAINT UK_CPF_WEBHOOK_IDEMP UNIQUE (ENDPOINT_ID, IDEMPOTENCY_KEY));
CREATE INDEX IX_CPF_WEBHOOK_DUE ON CPF_WEBHOOK_DELIVERY (ENDPOINT_ID, DELIVERY_STATE, NEXT_ATTEMPT_AT, DELIVERY_SEQUENCE);
CREATE TABLE CPF_INTEGRATION_CLOSURE_AUDIT (AUDIT_ID VARCHAR(64) NOT NULL, CATEGORY VARCHAR(64) NOT NULL, TARGET_ID VARCHAR(64) NOT NULL, ACTION_NAME VARCHAR(64) NOT NULL, ACTOR_ID VARCHAR(64) NOT NULL, ACTION_REASON VARCHAR(1000) NOT NULL, RESULT_STATE VARCHAR(64) NOT NULL, RESULT_DETAIL VARCHAR(1000), OCCURRED_AT TIMESTAMPTZ NOT NULL, PRIMARY KEY (AUDIT_ID));
